var data = msg.payload;
var emailData = [];

// Check AQI condition
if (data.aqi_ens >= 4) {
    emailData.push({
        type: 'aqi',
        subject: '🚨 Air Quality Alert - Poor AQI Detected',
        body: `ALERT: Poor Air Quality Detected!\n\n` +
              `Current AQI Level: ${data.aqi_ens}\n` +
              `Status: Unhealthy (≥4)\n` +
              `Temperature: ${data.temperature}°C\n` +
              `Humidity: ${data.humidity}%\n` +
              `Pressure: ${data.pressure} hPa\n\n` +
              `Recommendation: Consider staying indoors and using air purifiers.\n` +
              `Time: ${new Date().toLocaleString()}`,
        data: data
    });
}

// Check CO2 condition
if (data.eco2_ens >= 1000) {
    emailData.push({
        type: 'co2',
        subject: '⚠️ High CO2 Levels Alert',
        body: `WARNING: High CO2 Levels Detected!\n\n` +
              `Current CO2 Level: ${data.eco2_ens} ppm\n` +
              `Status: High (≥1000 ppm)\n` +
              `TVOC: ${data.tvoc_ens}\n` +
              `Temperature: ${data.temperature}°C\n` +
              `Humidity: ${data.humidity}%\n\n` +
              `Recommendation: Increase ventilation immediately. Open windows or turn on fans.\n` +
              `Time: ${new Date().toLocaleString()}`,
        data: data
    });
}

// Check Smoke/Gas condition (MQ135)
if (data.mq135_value >= 990) {
    emailData.push({
        type: 'smoke',
        subject: '🔥 Smoke/Gas Detection Alert - URGENT',
        body: `URGENT: Smoke or Hazardous Gas Detected!\n\n` +
              `MQ135 Sensor Value: ${data.mq135_value}\n` +
              `Status: Critical (≥990)\n` +
              `AQI: ${data.aqi_ens}\n` +
              `CO2: ${data.eco2_ens} ppm\n` +
              `Temperature: ${data.temperature}°C\n\n` +
              `IMMEDIATE ACTION REQUIRED:\n` +
              `- Check for smoke or fire\n` +
              `- Ensure proper ventilation\n` +
              `- Consider evacuating if necessary\n\n` +
              `Time: ${new Date().toLocaleString()}`,
        data: data
    });
}

// Send each email as separate message
if (emailData.length > 0) {
    var messages = [];
    for (var i = 0; i < emailData.length; i++) {
        messages.push({
            payload: emailData[i].data,
            topic: emailData[i].subject,
            email_body: emailData[i].body,
            alert_type: emailData[i].type
        });
    }
    return [messages];
}

return null;

// Rate limiting to prevent email spam
// Store last email times in context
var lastEmails = context.get('lastEmails') || {};
var currentTime = Date.now();
var cooldownPeriod = 1 * 60 * 1000; // 1 minutes in milliseconds

var alertType = msg.alert_type;

// Check if we've sent this type of alert recently
if (lastEmails[alertType] && (currentTime - lastEmails[alertType] < cooldownPeriod)) {
    // Skip this email - too soon since last one
    node.warn(`Email rate limited for ${alertType} alert. Last sent ${Math.round((currentTime - lastEmails[alertType])/1000/60)} minutes ago.`);
    return null;
}

// Update last email time for this alert type
lastEmails[alertType] = currentTime;
context.set('lastEmails', lastEmails);

// Pass the message through
return msg;

// Configure email settings
msg.to = "your-email@example.com";  // Replace with your email
msg.subject = msg.topic;  // Subject was set in the condition check
msg.payload = msg.email_body;  // Body was set in the condition check


return msg;

var data = msg.payload;

// Set the 'led' variable to 1 if aqi_ens is 4 or higher, otherwise 0.
var led = (data.aqi_ens >= 4) ? 1 : 0;
var led2 = (data.eco2_ens >= 1000) ? 1 : 0;
var led3 = (data.mq135_value >= 990) ? 1 : 0;

msg.payload = data;
msg.alert = (data.aqi_ens >= 4);

if (msg.alert) {
  node.warn('ALERT: Poor Air Quality - AQI: ' + data.aqi_ens);
}

// Prepare HTTP URLs (replace YOUR_AUTH_TOKEN)
var auth = 'YOUR_BLYNK_AUTH_TOKEN';

// Individual URLs for dashboard updates
msg.tempUrl = `https://blynk.cloud/external/api/update?token=${auth}&V1=${data.temperature.toFixed(1)}`;
msg.humUrl = `https://blynk.cloud/external/api/update?token=${auth}&V2=${data.humidity.toFixed(1)}`;
msg.pressUrl = `https://blynk.cloud/external/api/update?token=${auth}&V3=${data.pressure}`;
msg.ppmUrl = `https://blynk.cloud/external/api/update?token=${auth}&V4=${data.eco2_ens}`;
msg.aqiUrl = `https://blynk.cloud/external/api/update?token=${auth}&V5=${data.aqi_ens}`;
msg.tvocUrl = `https://blynk.cloud/external/api/update?token=${auth}&V6=${data.tvoc_ens}`;
msg.mq135Url = `https://blynk.cloud/external/api/update?token=${auth}&V7=${data.mq135_value}`;
// The ledUrl now correctly uses the integer 'led' variable
msg.ledUrl = `https://blynk.cloud/external/api/update?token=${auth}&V8=${led}`;
msg.led2Url = `https://blynk.cloud/external/api/update?token=${auth}&V9=${led2}`;
msg.led3Url = `https://blynk.cloud/external/api/update?token=${auth}&V10=${led3}`;

// For notification: Log event
if (msg.alert) {
  msg.eventUrl = `https://blynk.cloud/external/api/logEvent?token=${auth}&code=air_quality_alert&description=Poor Air Quality Detected! AQI: ${data.aqi_ens}`;
}

return msg;
